def naturaldate(value: dt.date | dt.datetime) -> str:
    """Like `naturalday`, but append a year for dates more than ~five months away."""
    import datetime as dt

    original_value = value
    try:
        if isinstance(value, dt.datetime) and value.tzinfo is not None:
            today = dt.datetime.now(value.tzinfo).date()
        else:
            today = dt.date.today()  # noqa: DTZ011
        value_date = dt.date(value.year, value.month, value.day)
    except AttributeError:
        # Passed value wasn't date-ish
        return str(value)
    except (OverflowError, ValueError):
        # Date arguments out of range
        return str(value)

    delta_days = (value_date - today).days
    if abs(delta_days) >= 5 * 365 // 12:
        return naturalday(original_value, "%b %d %Y")

    # For today/tomorrow/yesterday, use the computed `today` instead of
    # calling naturalday which would use dt.date.today() and lose the timezone context
    if delta_days == 0:
        return _("today")
    if delta_days == 1:
        return _("tomorrow")
    if delta_days == -1:
        return _("yesterday")

    return naturalday(original_value)
